import copy

class TenantResults:
    def __init__(self):
        self._by_tenant = {}
    def append(self, tenant, result):
        if not isinstance(tenant, str) or not tenant:
            raise ValueError('tenant required')
        self._by_tenant.setdefault(tenant, []).append(result)
        return self.snapshot(tenant)
    def snapshot(self, tenant):
        if not isinstance(tenant, str) or not tenant:
            raise ValueError('tenant required')
        return [dict(item) if isinstance(item,dict) else list(item) if isinstance(item,list) else item for item in self._by_tenant.get(tenant, [])]
